def generate_span_id(self) -> int:
    span_id = random.getrandbits(64)
    while span_id == trace.INVALID_SPAN_ID:
        span_id = random.getrandbits(64)
    return span_id

def generate_trace_id(self) -> int:
    trace_id = random.getrandbits(128)
    while trace_id == trace.INVALID_TRACE_ID:
        trace_id = random.getrandbits(128)
    return trace_id
